                                note = note,
                                onDeleteClick = {
                                    viewModel.onEvent(AllNotesScreenEvents.DeleteNote(note))
                                    scope.launch {
                                        val result = snackbarHostState.showSnackbar(
                                            message = "Note deleted",
                                            actionLabel = "Undo"
                                        )
                                        if (result == SnackbarResult.ActionPerformed) {
                                            viewModel.onEvent(AllNotesScreenEvents.RestoreNote)
                                        }
                                    }
                                },
                                onNoteClick = {
                                    navigateToEditNote(note.id!!)
                                }
                            )
                        }
                    }
                }
            }
        }

        // Floating Action Button
        ExtendedFloatingActionButton(
            onClick = navigateToNewNote,
            modifier = Modifier
