@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SingleNoteScreen(
    viewModel: SingleNoteScreenViewModel = koinViewModel(),
    navigateBack: () -> Unit,
) {
    val state by viewModel.addEditNoteState.collectAsState()
    val noteBackgroundAnimatable = remember {
        Animatable(Color(state.noteColor))
    }
    val snackbarHostState = remember { SnackbarHostState() }
    val scope = rememberCoroutineScope()
    val keyboardController = LocalSoftwareKeyboardController.current
    val titleFocusRequester = remember { FocusRequester() }

    var showColorPicker by remember { mutableStateOf(false) }
    val scrollState = rememberScrollState()

    LaunchedEffect(state.noteColor) {
        noteBackgroundAnimatable.animateTo(
            targetValue = Color(state.noteColor),
            animationSpec = tween(durationMillis = 500)
        )
    }

    LaunchedEffect(key1 = true) {
        viewModel.eventFlow.collectLatest { event =>
            when (event) {
                is SingleNoteScreenEventResponse.ShowSnackbar -> {
                    snackbarHostState.showSnackbar(message = event.message)
                }
                is SingleNoteScreenEventResponse.SaveNote -> {
                    navigateBack()
                }
            }
        }
    }

    Scaffold(
        snackbarHost = { SnackbarHost(snackbarHostState) },
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = if (state.isEditingNote) "Edit Note" else "New Note",
                        style = MaterialTheme.typography.titleLarge.copy(
                            fontWeight = FontWeight.SemiBold
                        )
                    )
                },
                navigationIcon = {
                    IconButton(onClick = navigateBack) {
                        Icon(
                            imageVector = Icons.Default.ArrowBack,
                            contentDescription = "Back",
                            tint = MaterialTheme.colorScheme.onSurface
                        )
                    }
                },
                actions = {
                    IconButton(
                        onClick = { showColorPicker = !showColorPicker }
                    ) {
                        Icon(
                            imageVector = Icons.Default.Palette,
                            contentDescription = "Change color",
                            tint = MaterialTheme.colorScheme.onSurface
                        )
                    }

                    IconButton(
                        onClick = {
                            viewModel.onEvent(SingleNoteScreenEvents.SaveNote)
                            keyboardController?.hide()
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Default.Check,
                            contentDescription = "Save note",
                            tint = MaterialTheme.colorScheme.primary
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.surface,
                    titleContentColor = MaterialTheme.colorScheme.onSurface
                )
            )
        },
        containerColor = noteBackgroundAnimatable.value
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
        ) {
            // Color Picker Section
            AnimatedVisibility(
                visible = showColorPicker,
                enter = slideInVertically() + fadeIn(),
                exit = slideOutVertically() + fadeOut()
            ) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    color = MaterialTheme.colorScheme.surface.copy(alpha = 0.95f),
                    shadowElevation = 8.dp
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp)
                    ) {
                        Text(
                            text = "Choose a color",
                            style = MaterialTheme.typography.titleMedium.copy(
                                fontWeight = FontWeight.Medium
                            ),
                            color = MaterialTheme.colorScheme.onSurface,
                            modifier = Modifier.padding(bottom = 12.dp)
                        )

                        LazyRow(
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            contentPadding = PaddingValues(horizontal = 4.dp)
                        ) {
                            items(NoteColors) { color ->
                                val isSelected = color.toArgb() == state.noteColor

                                Box(
                                    modifier = Modifier
                                        .size(50.dp)
                                        .clip(CircleShape)
                                        .background(color)
                                        .border(
                                            width = if (isSelected) 3.dp else 0.dp,
                                            color = if (isSelected) MaterialTheme.colorScheme.primary else Color.Transparent,
                                            shape = CircleShape
                                        )
                                        .clickable {
                                            viewModel.onEvent(
                                                SingleNoteScreenEvents.ChangeColor(color.toArgb())
                                            )
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    if (isSelected) {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = "Selected",
                                            tint = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.size(24.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Note Content
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .verticalScroll(scrollState)
                    .padding(20.dp)
            ) {
                // Title Field
                HintedTransparentTextField(
                    text = state.noteTitle,
                    hint = "Enter title...",
                    onValueChange = {
                        viewModel.onEvent(SingleNoteScreenEvents.EnteredTitle(it))
                    },
                    onFocusChange = {
                        viewModel.onEvent(SingleNoteScreenEvents.ChangeTitleFocus(it))
                    },
                    isHintVisible = state.isHintVisible,
                    singleLine = true,
                    textStyle = MaterialTheme.typography.headlineSmall.copy(
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    ),
                    modifier = Modifier
                        .fillMaxWidth()
                        .focusRequester(titleFocusRequester)
                )

                Spacer(modifier = Modifier.height(16.dp))

                // Content Field
                HintedTransparentTextField(
                    text = state.noteContent,
                    hint = "Start writing your note...",
                    onValueChange = {
                        viewModel.onEvent(SingleNoteScreenEvents.EnteredContent(it))
                    },
                    onFocusChange = {
                        viewModel.onEvent(SingleNoteScreenEvents.ChangeContentFocus(it))
                    },
                    isHintVisible = state.isContentHintVisible,
                    textStyle = MaterialTheme.typography.bodyLarge.copy(
                        color = MaterialTheme.colorScheme.onSurface
                    ),
                    modifier = Modifier
                        .fillMaxWidth()
                        .fillMaxHeight()
                )
            }
        }
    }

    // Auto-focus title for new notes
    LaunchedEffect(state.isEditingNote) {
        if (!state.isEditingNote && state.noteTitle.isEmpty()) {
            titleFocusRequester.requestFocus()
        }
    }
}

