package com.example.notes.ui.utils

import kotlinx.datetime.*

object DateUtils {

    fun formatTimestamp(timestamp: Long): String {
        val noteInstant = Instant.fromEpochMilliseconds(timestamp)
        val nowInstant = Clock.System.now()
        val noteDate = noteInstant.toLocalDateTime(TimeZone.currentSystemDefault()).date
        val nowDate = nowInstant.toLocalDateTime(TimeZone.currentSystemDefault()).date

        val duration = nowInstant - noteInstant

        return when {
            duration < 1.minutes -> "Just now"
            duration < 1.hours -> "${duration.inWholeMinutes}m ago"
            duration < 1.days -> "${duration.inWholeHours}h ago"
            duration < 7.days -> "${duration.inWholeDays}d ago"
            noteDate.year == nowDate.year -> {
                "${noteDate.month.name.take(3)} ${noteDate.dayOfMonth}"
            }
            else -> {
                "${noteDate.month.name.take(3)} ${noteDate.dayOfMonth}, ${noteDate.year}"
            }
        }
    }

    fun formatLastModified(timestamp: Long): String {
        val noteInstant = Instant.fromEpochMilliseconds(timestamp)
        val nowInstant = Clock.System.now()
        val noteDate = noteInstant.toLocalDateTime(TimeZone.currentSystemDefault()).date
        val nowDate = nowInstant.toLocalDateTime(TimeZone.currentSystemDefault()).date

        val duration = nowInstant - noteInstant

        return when {
            duration < 1.minutes -> "just now"
            duration < 1.hours -> "${duration.inWholeMinutes}m ago"
            duration < 1.days -> "${duration.inWholeHours}h ago"
            noteDate == nowDate -> "today"
            noteDate == nowDate.minus(1, DateTimeUnit.DAY) -> "yesterday"
            duration < 7.days -> "${duration.inWholeDays}d ago"
            noteDate.year == nowDate.year -> {
                "${noteDate.month.name.take(3)} ${noteDate.dayOfMonth}"
            }
            else -> {
                "${noteDate.month.name.take(3)} ${noteDate.dayOfMonth}, ${noteDate.year}"
            }
        }
    }

    fun getCurrentTimestamp(): Long {
        return Clock.System.now().toEpochMilliseconds()
    }
}
